<script setup lang="ts">
import DateField from './DateField.vue';
import EventResearchDetail from './EventResearchDetail.vue';
import TranslationGovernance from './TranslationGovernance.vue';
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';import {safeOfficialUrl} from '../api/client';
import OfficialMonitor from './OfficialMonitor.vue';import {title,sourceName,indicator,utc,time as beijingTime,http} from '../presentation/zh';import {useRoute,useRouter} from 'vue-router';
const emit=defineEmits<{connection:[state:string]}>();
const props=defineProps<{embedded?:boolean;token?:string}>();
const route=useRoute(),router=useRouter(),menuOpen=ref(false);
const routes=['/official','/research','/macro','/brief','/sources','/settings'];
const names=['全球官方发布监控','金融事件研判','全球宏观监测','每日金融简报','数据源监控','系统设置'];
async function post<T>(path:string,body:unknown={}):Promise<T>{const response=await fetch('/api'+path,{method:'POST',headers:{'Content-Type':'application/json',...(props.token?{Authorization:'Bearer '+props.token}:{})},body:JSON.stringify(body)});if(!response.ok)throw new Error(`本地服务请求失败（${response.status}），请检查服务运行状态`);return response.json();}
type Row=Record<string,any>;const ready=ref(false),busy=ref(false),error=ref(''),tab=ref('全球官方发布监控');const tabs=['全球官方发布监控','金融事件研究卡片','全球宏观研究工作台','全球金融每日简报','官方数据可用性','SEC配置准备'];
watch([ready,busy],()=>emit('connection',ready.value?'查询接口已连接':busy.value?'正在连接':'查询接口未连接'),{immediate:true});
const catalog=ref<Row>({}),monitor=ref<Row>({}),cards=ref<Row[]>([]),proof=ref<Row>(),macro=ref<Row>(),analysis=ref<Row>(),resources=ref<Row>({}),sec=ref<Row>({}),brief=ref<Row>(),history=ref<Row[]>([]),series=ref(''),source=ref(''),topic=ref(''),date=ref(new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date())),watchOnly=ref(false),page=ref(0),copied=ref(false);
const state:Row={RECORDED:'有检查记录',STALE_RUNNING:'任务超时待核查',CHECK_FAILED:'最近检查失败',CHECK_OVERDUE:'检查间隔异常',SUCCESS:'检查成功',FAILED:'检查失败',RUNNING:'运行中',DISABLED:'停用',APPROVED:'许可已核查',PENDING:'待核查',FIELD_MATCHED:'字段一致',SOURCE_CONFIRMED:'来源确认',SOURCE_CHECKED:'官方来源已核查',EXTRACTED:'已提取待核实',INSUFFICIENT:'证据不足',INDEPENDENT_SUPPORTED:'独立支持',RULE_GENERATED:'规则生成',NO_MATCHING_DATA:'覆盖范围内暂无真实数据',HISTORICAL_BACKFILL:'历史回填',PENDING_CONFIGURATION:'待配置',NONE:'无翻译'};
const label=(s:any)=>s==null?'未知':state[s]||'待核查';const time=beijingTime;const url=(s:string)=>safeOfficialUrl(s)||(s?.startsWith('https://download.bls.gov/')&&!new URL(s).username);
const curve=computed(()=>{const points=new Map<string,number>();for(const r of macro.value?.observations||[]){if(r.value!=null&&!points.has(r.observation_date))points.set(r.observation_date,Number(r.value));}const data=[...points].filter(([d,n])=>Number.isFinite(n)).sort(([a],[b])=>a.localeCompare(b)).slice(-30);if(data.length<2)return '';const lo=Math.min(...data.map(x=>x[1])),hi=Math.max(...data.map(x=>x[1]));return data.map(([d,n],i)=>`${20+i*560/(data.length-1)},${hi===lo?90:150-(n-lo)/(hi-lo)*120}`).join(' ');});
const query=()=>({date:date.value,source:source.value,topic:topic.value,watchOnly:watchOnly.value,page:page.value});
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await action();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function enter(){ready.value=false;await run(async()=>{catalog.value=await post<Row>('/practical/catalog');series.value=catalog.value.series?.[0]?.id||'';await load();ready.value=true;});}
async function load(){proof.value=undefined;page.value=Math.max(0,page.value);if(tab.value===tabs[0])monitor.value=await post<Row>('/practical/monitor');if(tab.value===tabs[1])cards.value=await post<Row[]>('/practical/cards',query());if(tab.value===tabs[2]&&series.value)macro.value=await post<Row>('/practical/macro',{series:series.value,page:page.value});if(tab.value===tabs[3])history.value=await post<Row[]>('/practical/brief/query',query());if(tab.value===tabs[4]){resources.value=await post<Row>('/practical/resource/status');monitor.value=await post<Row>('/practical/monitor');}if(tab.value===tabs[5])sec.value=await post<Row>('/practical/sec/preflight');}
async function select(name:string){menuOpen.value=false;await router.push(routes[tabs.indexOf(name)]);}watch(()=>route.path,async path=>{const index=routes.indexOf(path);tab.value=tabs[index<0?0:index];document.title='寰瞰 · '+names[index<0?0:index];page.value=0;if(ready.value)await run(load);});function resetFilters(){source.value='';topic.value='';watchOnly.value=false;date.value=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());void refresh();}async function coverageDay(offset:number){const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());date.value=new Date(Date.parse(today+'T12:00:00+08:00')+offset*86400000).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});await refresh();}
async function refresh(){if(tab.value===tabs[3])brief.value=undefined;page.value=0;await run(load);}async function paginate(n:number){page.value=Math.max(0,page.value+n);await run(load);}
async function detail(id:string){await run(async()=>{proof.value=await post<Row>('/practical/card/detail',{id});});}
async function generate(){copied.value=false;await run(async()=>{brief.value=await post<Row>('/practical/brief/generate',query());await load();});}async function openBrief(id:string){copied.value=false;await run(async()=>{brief.value=await post<Row>('/practical/brief/detail',{id});});}
async function copy(){await run(async()=>{await navigator.clipboard.writeText(briefText());copied.value=true;});}
onMounted(()=>{const index=routes.indexOf(route.path);tab.value=tabs[index<0?0:index];document.title='寰瞰 · '+names[index<0?0:index];void enter();});
const monitorTimer=setInterval(()=>{if(ready.value&&[tabs[0],tabs[4]].includes(tab.value)&&!busy.value&&!document.hidden)void run(load);},30000);onUnmounted(()=>clearInterval(monitorTimer));
const sections:Row={coverage:'覆盖范围',official_events:'官方发布',macro_observations:'宏观数据变化',industry_events:'行业与企业信息',risks:'风险提示',research_events:'重点研究事件',impact_hypotheses:'事件影响假设',counter_evidence:'反面证据',supported_hypotheses:'有依据的研究假设',unverified_leads:'待核实线索',watch_variables:'后续关注变量',source_gaps:'数据源异常与缺口',evidence_catalog:'证据目录'};
function briefText(){if(!brief.value)return '';const b=brief.value;const format=(r:any)=>{if(typeof r==='string')return r;const lines=[r.original_title?title(r).text:sourceName(r.source_id,r.publisher||r.name||indicator(r.series_id)||'证据记录')];if(r.original_title)lines.push('官方原文标题：'+r.original_title,'翻译状态：'+title(r).status);if(r.value!==undefined)lines.push(`观测期 ${r.observation_date}：${r.value??'原始缺失值'}，单位见原指标定义，本地版本 ${r.version}`);if(r.published_at!==undefined)lines.push(`官方发布时间：${time(r.published_at,'官方发布时间未知')}；采集：${time(r.collected_at)}`);if(r.report?.mechanism)lines.push('规则假设：'+r.report.mechanism);if(r.error_code)lines.push('检查异常：'+label(r.status)+'，需核查是否遗漏');if(r.source_url)lines.push('原始来源：'+r.source_url);if(r.raw_content_hash)lines.push('证据SHA-256：'+r.raw_content_hash);return lines.join('\n');};return `寰瞰 全球金融每日简报\n覆盖：${time(b.coverage_start)}—${time(b.coverage_end)}\n查询：${time(b.queried_at)}\n规则：${b.rule_version}；模型未执行\n快照：${b.snapshot_id}\n`+Object.entries(sections).map(([k,title])=>title+'\n'+(k==='coverage'?'按上海时区日期与实际查询时点冻结；有界近期证据，非全量新闻总结':items(k).length?items(k).map(format).join('\n\n'):'覆盖范围内暂无真实数据')).join('\n\n');}

function items(k:string){const v=brief.value?.report[k];return Array.isArray(v)?v:[];}
</script>
<template><div :class="props.embedded?'embedded-research':'shell'"><aside v-if="!props.embedded" :class="{expanded:menuOpen}"><button class="mobile-menu" @click="menuOpen=!menuOpen" :aria-expanded="menuOpen">{{menuOpen?'收起导航':'展开导航'}}</button><div class="brand">寰瞰<span>HUANKAN · 全球金融情报</span></div><nav><button v-for="name in tabs" :key="name" :class="{active:tab===name}" @click="select(name)" :disabled="!ready||busy">{{ names[tabs.indexOf(name)] }}</button></nav><p class="muted">来源证据与研究假设分开呈现。<br>仅使用真实入库资料。</p><a href="http://127.0.0.1:5173/" target="_blank" rel="noopener">全球实时情报 · 观察中的主站</a></aside><div class="research-content"><header v-if="!props.embedded"><h1>{{ names[tabs.indexOf(tab)] }}</h1><span class="connection">{{ ready?'查询接口已连接':busy?'正在连接':'查询接口未连接' }}</span></header>
<section v-if="!ready" class="panel"><h2>{{ busy?'正在连接本地查询服务':'本地查询服务暂不可用' }}</h2><p>页面自动连接本机服务，无需填写访问密钥。</p><button v-if="!busy" class="primary" @click="enter">重新连接</button></section>
<p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="busy" class="muted">正在读取真实数据库，请稍候…</p>
<template v-if="ready"><EventResearchDetail v-if="tab===tabs[1]&&typeof route.query.event==='string'" :id="route.query.event" :token="props.token"/><a v-if="tab===tabs[1]&&route.query.event" href="#/research">返回事件列表</a><details v-if="(tab===tabs[1]&&!route.query.event)||tab===tabs[3]" class="panel filter-panel" :open="true"><summary>查询条件</summary><div class="filters"><label>来源 <select aria-label="来源" v-model="source"><option value="">全部来源</option><option v-for="s in catalog.sources" :value="s.id">{{ sourceName(s.id,s.name) }}</option></select></label><label>专题 <select aria-label="专题" v-model="topic"><option value="">全部专题</option><option v-for="t in catalog.topics">{{ t.replace('AI','人工智能（AI）') }}</option></select></label><button v-if="tab===tabs[3]" :disabled="busy" @click="coverageDay(0)">今天</button><button v-if="tab===tabs[3]" :disabled="busy" @click="coverageDay(-1)">昨天</button><label v-if="tab===tabs[3]">简报覆盖日期（北京时间） <DateField aria-label="日期" v-model="date"/></label><label><input v-model="watchOnly" type="checkbox">仅看个人关注</label><button @click="refresh" :disabled="busy">查询</button><button @click="resetFilters" :disabled="busy">重置</button></div></details>
<OfficialMonitor v-if="tab===tabs[0]||tab===tabs[4]" :health-only="tab===tabs[4]" :monitor="monitor" :catalog="catalog" :token="props.token"/>
<section v-if="tab===tabs[1]&&!route.query.event" class="panel feed"><p class="muted">仅显示合规官方来源。每页最多50条，同源主事件保留全部证据版本。</p><p v-if="!cards.length" class="empty">暂无真实数据</p><article v-for="c in cards" :key="c.id"><h2>{{ title(c).text }}</h2><p class="muted">{{title(c).status}}</p><details><summary>查看官方原文标题</summary><p class="original">{{c.original_title}}</p></details><p>事件类型：{{ c.category }}；证据版本数：{{ c.evidence_versions }}</p><p>{{ sourceName(c.source_id,c.publisher) }} · 规则优先级 {{ c.research_priority }}（不等同市场重要性）</p><p>官方发布时间：{{ c.published_at?time(c.published_at):'官方发布时间未知' }}；首次发现：<time :title="'UTC原值：'+utc(c.first_seen_at)">{{time(c.first_seen_at)}}</time>；采集：<time :title="'UTC原值：'+utc(c.collected_at)">{{time(c.collected_at)}}</time>；{{ label(c.ingestion_kind) }}</p><p>{{ c.fact_boundary }}</p><p>{{ c.importance_boundary }}</p><p v-if="c.actual_observation_period">观测期：{{ c.actual_observation_period }}；关键数字：{{ c.key_numbers??'原始缺失值' }}</p><p v-if="c.historical_comparison">前期 {{ c.historical_comparison.observation_date }}：{{ c.historical_comparison.value??'缺失' }}；同口径差值：{{ c.historical_comparison.difference??'不能比较' }}，不计算超预期。</p><p v-for="f in c.facts">事实状态：{{ label(f.status) }}；{{ f.fields.actual_value!==undefined?'实际值：'+(f.fields.actual_value??'原始缺失')+(f.fields.unit||''):f.fields.original_title||'实质字段见原始证据，未补造' }}</p><p>传导机制假设：{{ c.mechanism }}</p><p>可能关联市场：{{ c.possible_markets.join('；') }}</p><p>反向解释：{{ c.counter_explanation }}</p><p>缺失证据：{{ c.missing_evidence.join('；') }}</p><p>后续变量：{{ c.watch_variables.join('；') }}</p><p>市场验证：{{ c.market_status }}；模型执行：未执行</p><a v-if="url(c.source_url)" :href="c.source_url" target="_blank" rel="noopener">查看原始来源</a><button @click="router.push({path:'/research',query:{event:c.id}})">打开完整研究详情</button><button @click="detail(c.id)">查看证据与时间线</button></article><div v-if="proof" class="proof"><h3>事件证据版本</h3><article v-for="r in proof.evidence" :key="r.id"><p>官方发布时间 {{ r.published_at?time(r.published_at):'官方发布时间未知' }} · 采集 <time :title="'UTC原值：'+utc(r.collected_at)">{{time(r.collected_at)}}</time> · 版本 {{ r.revision }} · 哈希{{ r.hash_passed?'通过':'失败' }}</p><code>{{ r.raw_content_hash }}</code><a v-if="url(r.source_url)" :href="r.source_url" target="_blank" rel="noopener">查看原始来源</a></article></div></section>
<section v-if="tab===tabs[2]" class="panel feed"><label>真实指标 <select v-model="series" @change="refresh"><option v-for="s in catalog.series" :value="s.id">{{ indicator(s.id)||'指标中文名称待核验' }}</option></select></label><template v-if="macro"><h2>{{ indicator(series)||'指标中文名称待核验' }}</h2><details><summary>查看指标原名与报价口径</summary><p class="original">{{macro.definition.title}}</p><p>{{series}}</p><p>{{series.startsWith('EXR.')?'官方日度参考汇率，1欧元对应所示币种数量，不是实时成交价':'央行政策利率，按原指标定义'}}</p></details><p>{{ sourceName(macro.definition.source_id,macro.definition.publisher) }} · 单位：{{ macro.definition.units }} · 频率：{{ macro.definition.frequency==='D'?'日度':macro.definition.frequency==='M'?'月度':macro.definition.frequency==='B'?'政策变更日':'按官方口径' }}</p><p>{{ macro.version_boundary?.replace('vintage','历史版本') }}</p><svg v-if="curve" viewBox="0 0 600 180" role="img" aria-label="真实宏观历史观测曲线"><polyline :points="curve" fill="none" stroke="#77d7d9" stroke-width="2"/></svg><p v-if="curve" class="muted">最近最多30个真实观测期，横轴按观测顺序；重复日期取最新本地版本，缺失值不补齐。</p><button @click="run(async()=>{analysis=await post('/practical/macro/analyze',{series,asOf:new Date().toISOString()})})">冻结同口径研究快照</button><div v-if="analysis"><h3>同口径比较结果</h3><p>当前值：{{ analysis.report.fact_summary.current?.value??'缺失' }}；前值：{{ analysis.report.fact_summary.previous?.value??'缺失' }}；差值：{{ analysis.report.fact_summary.difference??'无法比较' }}</p><p>比较状态：{{analysis.report.fact_summary.comparison_status}}；差值单位：{{analysis.report.fact_summary.difference_unit||'未提供'}}</p><p>相对变化率：{{analysis.report.fact_summary.percent_change??'不能计算'}}；月度环比：{{analysis.report.fact_summary.mom_percent_change??'不满足连续月度条件'}}；同比：{{analysis.report.fact_summary.yoy_percent_change??'上年同期证据不足'}}（比例值单位为百分比）</p><p>{{analysis.report.fact_summary.seasonal_adjustment_note}}</p><details><summary>查看公式、计算输入与版本</summary><pre>{{JSON.stringify(analysis.report.fact_summary,null,2)}}</pre></details><p>{{ analysis.report.mechanism }}</p><p>{{ analysis.report.market_status }}；真实市场预期未知。</p><p>证据截止：<time :title="'UTC原值：'+utc(analysis.as_of)">{{time(analysis.as_of)}}</time>；规则版本 {{ analysis.rule_version }}</p></div><p v-if="!macro.observations?.length" class="empty">暂无真实数据</p><article v-for="r in macro.observations" :key="r.id"><h3>{{ r.observation_date }} · {{ r.value??'原始缺失值' }} {{ macro.definition.units }}</h3><p>本地观测版本 {{ r.version }}；发布时间 <time :title="'UTC原值：'+utc(r.published_at)">{{time(r.published_at,'官方发布时间未知')}}</time>；采集 <time :title="'UTC原值：'+utc(r.collected_at)">{{time(r.collected_at)}}</time>；源端历史版本未知</p><a v-if="url(r.source_url)" :href="r.source_url" target="_blank" rel="noopener">查看原始来源</a><code>{{ r.raw_content_hash }}</code></article></template><p v-else class="empty">暂无真实指标</p></section>
<section v-if="tab===tabs[3]" class="panel feed"><button class="primary" @click="generate" :disabled="busy">生成规则简报</button><p>每次生成冻结独立快照，保留旧版本。官方发布按发布时间筛选；宏观记录按真实采集时间筛选。来源、专题与个人关注均作用于内容范围。</p><template v-if="brief"><h2>全球金融每日简报</h2><p>本快照官方事件 {{items('official_events').length}} 条；待核聚合线索 {{items('unverified_leads').length}} 条，分别计数；两者均为有界内容，不能视为全日重大事件总数。</p><p>{{brief.report.priority_boundary}}</p><p>{{ label(brief.status) }} · {{ brief.rule_version }} · 无模型执行</p><p>覆盖：<time :title="'UTC原值：'+utc(brief.coverage_start)">{{time(brief.coverage_start)}}</time>—<time :title="'UTC原值：'+utc(brief.coverage_end)">{{time(brief.coverage_end)}}</time>；查询：<time :title="'UTC原值：'+utc(brief.queried_at)">{{time(brief.queried_at)}}</time></p><code>快照 {{ brief.snapshot_id }}；输入哈希 {{ brief.input_hash }}</code><button :disabled="busy" @click="copy">{{ copied?'已复制':'复制简报文本' }}</button><section v-for="(sectionTitle,k) in sections" :key="k"><h3>{{ sectionTitle }}</h3><p v-if="k==='coverage'">以上海时区日期为界，数据截止实际查询时间。每节数量受有界分页限制。</p><p v-else-if="!items(String(k)).length">覆盖范围内暂无真实数据</p><article v-for="(r,i) in items(String(k))" :key="i"><template v-if="typeof r==='string'">{{ r }}</template><template v-else><p>{{ r.original_title?title(r).text:sourceName(r.source_id,r.publisher||r.name||indicator(r.series_id)||'证据记录') }}</p><details v-if="r.original_title"><summary>查看原文标题</summary><p class="original">{{r.original_title}}</p></details><p v-if="r.value!==undefined">{{ r.observation_date }}：{{ r.value??'缺失值' }}（按原指标单位）；本地版本 {{ r.version }}</p><details v-if="r.priority_reasons"><summary>研究优先级依据</summary><p v-for="why in r.priority_reasons">{{why}}</p></details><p v-if="r.report?.mechanism">规则假设：{{ r.report.mechanism }}</p><a v-if="r.original_title&&r.id" :href="'#/research?event='+r.id">查看金融事件研究详情</a><p v-if="r.original_title">{{ title(r).status }}</p><p v-if="r.published_at!==undefined">官方发布时间 <time :title="'UTC原值：'+utc(r.published_at)">{{time(r.published_at,'官方发布时间未知')}}</time>；采集 <time :title="'UTC原值：'+utc(r.collected_at)">{{time(r.collected_at)}}</time></p><p v-if="r.error_code">最近任务存在异常，可能遗漏；{{http(r.http_status)}}；诊断详情可在数据源监控核查。</p><a v-if="r.source_url&&url(r.source_url)" :href="r.source_url" target="_blank" rel="noopener">查看原始来源</a><code v-if="r.raw_content_hash">{{ r.raw_content_hash }}</code></template></article></section><p>{{ brief.report.generation }}。{{ brief.report.unknown_publication }}</p></template><h3>历史简报版本</h3><article v-for="h in history" :key="h.id"><p><time :title="'UTC原值：'+utc(h.coverage_start)">{{time(h.coverage_start)}}</time>—<time :title="'UTC原值：'+utc(h.coverage_end)">{{time(h.coverage_end)}}</time> · {{ label(h.status) }}</p><p>生成 <time :title="'UTC原值：'+utc(h.queried_at)">{{time(h.queried_at)}}</time> · {{ h.rule_version }}</p><button :disabled="busy" @click="openBrief(h.id)">查看历史简报</button></article></section>
<section v-if="tab===tabs[4]" class="panel feed"><h2>美国劳工统计局（BLS）合规访问诊断</h2><p>{{ resources.state }}。同一路径24小时内最多一次显式诊断，不绕过限制。</p><button @click="run(async()=>{await post('/practical/resource/diagnose');await load()})" :disabled="busy">执行有界诊断</button><button @click="run(async()=>{await post('/practical/calendar/sync');await load()})" :disabled="busy">读取已获准官方日历</button><button @click="run(async()=>{await post('/practical/bls-file/sync',{first:2025,last:2026});await load()})" :disabled="busy">导入已验证居民消费价格指数（CPI）官方文件</button><article v-for="r in resources.requests" :key="r.id"><p>{{ r.url }}</p><p>请求 <time :title="'UTC原值：'+utc(r.requested_at)">{{time(r.requested_at)}}</time>；{{ http(r.http_status) }}；{{ r.error==='REQUEST_RESERVED'?'请求预算已预留':r.error?'失败，不生成业务数据':'响应已保存' }}；响应 {{ r.response_bytes??0 }} 字节</p><p>按24小时诊断预算，下次最早允许尝试：{{time(new Date(Date.parse(r.requested_at)+86400000).toISOString())}}；如官方要求更长等待，应遵从响应要求。</p><code v-if="r.sha256">{{ r.sha256 }}</code></article></section>
<TranslationGovernance v-if="tab===tabs[5]" :token="props.token"/><section v-if="tab===tabs[5]" class="panel feed"><h2>美国证券交易委员会（SEC）配置准备</h2><p>真实联系方式：{{ sec.contact_configured?'已配置':'待配置' }}；自动采集：{{ sec.automatic_enabled?'已启用':'关闭' }}</p><p>结构化财报数据（XBRL）：{{ sec.xbrl_model }}</p><p>已准备表单类型：{{ sec.forms?.join('、') }}</p><p>{{ sec.limit }}</p><p>{{ sec.state }}</p><p>请设置真实联系邮箱（SEC_CONTACT_EMAIL）、包含真实联系信息的请求标识（SEC_USER_AGENT）和官方公司编号关注名单（SEC_FOLLOWED_CIKS），先完成许可核查及预检再启用。不生成虚构联系方式。</p></section>
<section v-if="tab===tabs[5]" class="panel feed"><h2>美联储经济数据库（FRED）配置指南</h2><p>在本地服务环境中设置真实接口密钥（FRED_API_KEY）、允许使用的指标名单（FRED_SERIES_WHITELIST）及合法用途许可；预检通过后才启用 FRED_ENABLED。密钥不填写到页面，不在日志或截图中展示。未就绪时保持关闭。</p><p>美国劳工统计局（BLS）返回访问限制时保留原始响应，遵守重试预算；来源监控展示最近真实请求，不绕过限制。</p></section><footer v-if="tab===tabs[1]||tab===tabs[2]||tab===tabs[3]"><button @click="paginate(-1)" :disabled="page===0||busy">上一页</button><span>第{{ page+1 }}页</span><button @click="paginate(1)" :disabled="busy">下一页</button></footer></template></div></div></template>
